#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
# Optional machine-local paths, generated by tools/setup_linux.sh.
if [ -f "$ROOT/.local/environment.sh" ]; then source "$ROOT/.local/environment.sh"; fi

# Keep the system Java selection unchanged. Prefer an explicit project override.
supports_gradle() {
    local version
    [ -x "$1/bin/java" ] || return 1
    version="$("$1/bin/java" -version 2>&1 | sed -n 's/.*version "\([0-9]*\).*/\1/p' | head -1)"
    [ -n "$version" ] && [ "$version" -ge 17 ] && [ "$version" -le 23 ]
}
if [ -n "${OPSTATE_JAVA_HOME:-}" ]; then
    if ! supports_gradle "$OPSTATE_JAVA_HOME"; then
        echo 'OPSTATE_JAVA_HOME must point to JDK 17–23.' >&2
        exit 1
    fi
    export JAVA_HOME="$OPSTATE_JAVA_HOME"
elif ! supports_gradle "${JAVA_HOME:-/nonexistent}"; then
    for candidate in "/opt/homebrew/opt/openjdk/libexec/openjdk.jdk/Contents/Home" "/usr/lib/jvm/java-17-openjdk-amd64" "/usr/lib/jvm/java-21-openjdk-amd64"; do
        if supports_gradle "$candidate"; then export JAVA_HOME="$candidate"; break; fi
    done
    if ! supports_gradle "${JAVA_HOME:-/nonexistent}" && [ -x /usr/libexec/java_home ]; then
        for version in 21 17 23; do
            candidate="$(/usr/libexec/java_home -v "$version" 2>/dev/null || true)"
            if supports_gradle "$candidate"; then export JAVA_HOME="$candidate"; break; fi
        done
    fi
fi
if ! supports_gradle "${JAVA_HOME:-/nonexistent}"; then
    echo 'Set JAVA_HOME or OPSTATE_JAVA_HOME to a JDK 17–23 installation (JDK 17 or 21 recommended).' >&2
    exit 1
fi
exec "$ROOT/gradlew" -p "$ROOT" "$@"
